head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.MSG_TR_DOME = "작업이 정상적으로 처리되었습니다.";
scwin.MSG_TR_FAIL = "처리 중 오류가 발생하였습니다.";
scwin.MSG_NO_UPDT = "저장할 수정내용이 없습니다.";
scwin.MSG_NO_RECD = "삭제할 자료가 없습니다.";
scwin.MSG_NO_ACPT = "접수되지 않은 예비심사청구내용은 저장할 수 없습니다.";
scwin.MSG_AL_ACPT = "이미 접수 처리되었습니다.";
scwin.MSG_RQ_ISUR = "발행기관코드가 입력되지 않았거나 작업대상이 지정되지 않았으므로 작업을 수행할수 없습니다.";
scwin.panDisabled = false;
keyDisabled = true;
setResv = false;

scwin.fn_GetPar, scwin.fn_SetPar, scwin.strKeyBzProcsNo = "", scwin.strKeyIsurCd = "", scwin.fn_GetParOpn, scwin.fn_SetParOpn;
scwin.arrPanDisabled = new Array();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_FileAdd_onclick
 * @description 「첨부파일」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_FileAdd_onclick = function(e) {
    try {
        scwin.fileAdd(scwin.strKeyBzProcsNo);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05004.btn_FileAdd_onclick" });
    }
};

/**
 * @method
 * @name img_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Save_onclick = async function(e) {
    try {
        if (scwin.strKeyBzProcsNo === "") {
            alert(scwin.MSG_RQ_ISUR);
            return;
        }
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05004.img_Save_onclick" });
    }
};

/**
 * @method
 * @name img_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Acpt_onclick = async function(e) {
    try {
        if (scwin.strKeyBzProcsNo === "") {
            alert(scwin.MSG_RQ_ISUR);
            return;
        }

        /* 접수시 청구순번을 반영하도록 변경하여 주석처리함.
        if (med_ClmSeq.text == "") {
        	alert(cmb_BillSubmitDd.text.replace(/-/g, ""));

        	var url = 	"/listingCommon.do?method=listGeneral" +
        				"&outputMessageId=PRELISTING_KOSDAQ_NEW_SEQ_OUT" +
        				"&service=krx.lds.stf.listingcommon.services.ListingCommonApp" +
        				"&queryId=lds.stf.lstproc.prelistingkosdaq.select.newseq.condition"+
        				"&{P}=" + cmb_BillSubmitDd.text.replace(/-/g, "");
        	dts_Seq.DataID = encodeURI(url);
        	dts_Seq.reset();

        	alert(dts_Seq.NameString(dts_Seq.RowPosition, "NEW_SEQ"));

        	med_ClmSeq.text = dts_Seq.NameString(dts_Seq.RowPosition, "NEW_SEQ");
        }
         */

        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05004.img_Acpt_onclick" });
    }
};

/**
 * @method
 * @name img_Resv_onclick
 * @description 「유보」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Resv_onclick = async function(e) {
    try {
        if (scwin.strKeyBzProcsNo === "") {
            alert(scwin.MSG_RQ_ISUR);
            return;
        }
        await scwin.resv();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05004.img_Resv_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function(e) {
    try {
        frame.closeFrame();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05004.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function(e) {
    try {
        if (txb_IsurCd.getValue() !== "") {
            tab.ActiveIndex = 1;
            await scwin.searchSubmitDate(txb_IsurCd.getValue(), "");
        } else {
            alert(scwin.MSG_RQ_ISUR);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05004.img_Search_onclick" });
    }
};

