 * @returns {void}
 * @hidden N
 */
scwin.dts_ReqInf_OnLoadCompleted = function(rowcount) {
    try {
        scwin.setPanReadOnlyOnLoad(dts_ReqInf, pan_ReqInf);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05004.dts_ReqInf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EntInf_OnLoadCompleted
 * @description dts_EntInf 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EntInf_OnLoadCompleted = function(rowcount) {
    try {
        chk_VentspeclcsApplYn.checked = (dts_EntInf.NameString(1, "VENTSPECLCS_APPL_YN") === "Y"); // 벤처특례적용여부

        chk_VentspeclcsProgYysYn.checked = (dts_EntInf.NameString(1, "VENTSPECLCS_PROG_YYS_YN") === "Y"); // 벤처특례경과년수여부
        // chk_VentspeclcsCapYn.checked           = (dts_EntInf.NameString(1, "VENTSPECLCS_CAP_YN") == "Y");               // 벤처특례자본금여부
        // chk_VentspeclcsRoeYn.checked           = (dts_EntInf.NameString(1, "VENTSPECLCS_ROE_YN") == "Y");               // 벤처특례ROE여부
        // chk_VentspeclcsDebtAmtRtoYn.checked    = (dts_EntInf.NameString(1, "VENTSPECLCS_DEBT_AMT_RTO_YN") == "Y");      // 벤처특례부채금액비율여부

        chk_GrwthVentspeclcsYn.checked = (dts_EntInf.NameString(1, "GRWTH_VENTSPECLCS_YN") === "Y"); // 성장벤처특례여부

        chk_GrwthVentspeclcsOrdnincmYn.checked = (dts_EntInf.NameString(1, "GRWTH_VENTSPECLCS_ORDNINCM_YN") === "Y"); // 성장벤처특례경상이익여부

        chk_GrwthVentspeclcsRoeYn.checked = (dts_EntInf.NameString(1, "GRWTH_VENTSPECLCS_ROE_YN") === "Y"); // 성장벤처특례ROE여부

        scwin.setCurUnt();
        let s = "",
            d;
        d = scwin.getDtsOnTab();
        for (i = 1; i <= d.CountColumn; i++) {

            s = s + "\n" + d.ColumnID(i) + ":" + d.ColumnString(1, i);
        }
        log.setValue(log.getValue() + "\n" + s);

        scwin.setPanReadOnlyOnLoad(d, pan_Pub);

        /* ChM-000002723  20100903
	       1. 재상장 법인인 경우 공모 관련 항목 모두 비활성화
	       cmb_InvstgClmTpCd  : 심사청구 -재등록(5)
         */

        scwin.pubofr(dts_EntInf.NameValue(1, "INVSTG_CLM_TP_CD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05004.dts_EntInf_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Fin_OnLoadCompleted
 * @description dts_Fin 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Fin_OnLoadCompleted = function(rowcount) {
    try {
        med_RecentAcntgPdStrtYymm.setValue(dts_Fin.NameValue(1, "RECENT_ACNTG_PD_STRT_YYMM"));

        med_RecentAcntgPdEndYymm.setValue(dts_Fin.NameValue(1, "RECENT_ACNTG_PD_END_YYMM"));

        med_FiscalYy2.setValue(dts_Fin.NameValue(1, "FISCAL_YY"));

        med_AcntclsMm2.setValue(dts_Fin.NameValue(1, "ACNTCLS_MM"));
        scwin.wrtGrdFinTop();
        scwin.wrtGrdFinBtm();
        let s = "",
            d;
        d = scwin.getDtsOnTab();
        for (i = 1; i <= d.CountColumn; i++) {

            s = s + "\n" + d.ColumnID(i) + ":" + d.ColumnString(1, i);
        }
        log.setValue(log.getValue() + "\n" + s);

        scwin.setPanReadOnlyOnLoad(d, pan_Fin);

        /* ChM-000002723  20100903
	        재상장 법인인 경우 재무사항에서 대차대조표 항목만 입력
	       cmb_InvstgClmTpCd  : 심사청구 -재등록(5)
         */

        scwin.acc(dts_EntInf.NameValue(1, "INVSTG_CLM_TP_CD"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05004.dts_Fin_OnLoadCompleted" });
    }
};

