/**
 * @method
 * @name img_SetExamprnEmpNm_onclick
 * @description img_SetExamprnEmpNm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_SetExamprnEmpNm_onclick = function(e) {
    try {
        if (!keyDisabled) {
            scwin.fn_GetPar = scwin.getParExpEmp;
            scwin.fn_SetPar = scwin.setParExpEmp;

            const options = {
                id: "ULDSTF92018",
                title: "심사자선택",
                type: "browserPopup",
                width: 360 + 5,
                height: 400 + 30,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../listingcommon/ULDSTF92018.gfm", options);
        }
    } catch (ex) {
