/**
 * @method
 * @name tr_Sav_OnSuccess
 * @description tr Sav On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tr_Sav_OnSuccess = async function() {
    try {
        alert(scwin.MSG_TR_DOME);
        if (setResv) {

            if (scwin.fn_SetParOpn !== undefined) {
                let arr = new Array();

                scwin.fn_SetParOpn(arr);
            }

            $c.win.closePopup();
        } else {
            await scwin.search(scwin.strKeyBzProcsNo);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05004.tr_Sav_OnSuccess" });
    }
};

