/**
 * @method
 * @name searchSubmitDate
 * @description search Submit Date 처리
 * @param {*} strKey strKey
 * @param {*} strPar strPar
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchSubmitDate = async function(strKey, strPar) {
    // 발행기관번호,  업무처리번호(목록에서 현재폼 호출시의 매개변수가 지정되고 조회버튼 누른경우 "")
    scwin.strKeyIsurCd = strKey;
    const sbmOptions = {
        id : "sbm_dts_SmtDte",
        action : "/prelistingKosdaq.do",
        ref : "",
        target : "dts_SmtDte=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "";
    for (let i = 1; i <= dts_SmtDte.CountRow; i++) {

        strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_SmtDte.NameValue(i, "BZ_PROCS_NO") + "^" + dts_SmtDte.NameString(i, "BILL_SUBMIT_DD_DISP");
    }
    cmb_BillSubmitDd.CBData = strCbd;

    cmb_BillSubmitDd.Index = (strPar === "" ? 0 : cmb_BillSubmitDd.Index = cmb_BillSubmitDd.IndexOfColumn("BZ_PROCS_NO", strPar));
    if (cmb_BillSubmitDd.Index > -1) {
        await scwin.search(cmb_BillSubmitDd.BindColVal);
    } else {
        await scwin.search("");
    }
};

