    let bufDid = grd_FinBtm.DataID; // grid의 움직임을 방지하기 위하여 DataID를 임시로 보관, 작업후 원상복구
    grd_FinBtm.DataID = "";
    dts_FinBuf2.ClearData();
    dts_FinBuf2.setBroadcast(false);
    for (i = 0; i < Math.ceil(com.wconv.length(accMapBtm) / 2); i++) {
        dts_FinBuf2.insertRow();
        // 계정과목을 write

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        curRow = dts_FinBuf2.CountRow; /*ORG SRC: dts_FinBuf2.NameValue(curRow, "ACC_NM_1") = getString(" ", Math.min(accMapBtm[i].colDpt - 1, 0) * 4) +*/ X = scwin.getString(" ", Math.min(accMapBtm[i].colDpt - 1, 0) * 4) + accMapBtm[i].colCap; /*ORG SRC: dts_FinBuf2.NameValue(curRow, "ACC_NM_2") = getString(" ", Math.min(accMapBtm[i].colDpt - 1, 0) * 4) +*/ X = scwin.getString(" ", Math.min(accMapBtm[i].colDpt - 1, 0) * 4) + accMapBtm[scwin.getRgtIdxBtm(i)].colCap;
        // 계정값을 write
        for (j = 0; j < com.wconv.length(accIdxBtm); j++) {
            // 4개의 전기, 전전기컬럼에 표시
            // 표시컬럼이 우측일 경우 array의 절반크기만큼 추가된 인덱스로 배열을 참조해야 한다.

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            arrIdx = (accIdxBtm[j].colIdx > Math.ceil(dts_FinBuf2.CountColumn / 2) ? scwin.getRgtIdxBtm(i) : i); /*ORG SRC: dts_FinBuf2.ColumnValue(curRow, accIdxBtm[j].colIdx) = dts_Fin.NameValue(1, // dts_Fin에는 1row만 존재한다.*/ X = dts_Fin.NameValue(1, // dts_Fin에는 1row만 존재한다.
                accIdxBtm[j].colHdr + "_" + accMapBtm[arrIdx].colFtr);
        }
    }
    dts_FinBuf2.setBroadcast(true, true);
    dts_FinBuf2.RowPosition = 1;
    grd_FinBtm.DataID = bufDid; // grid에 dataset 내용 표시
};

/**
 * @method
 * @name wrtDstFinTop
 * @description 2계정이 1row로 구성된 dts_FinBuf의 내용을 transaction을 수행하기 위해 1row로 구성된 dts_Fin로 변환한다.
 * @returns {void}
 * @hidden N
 */
scwin.wrtDstFinTop = function() {
    // 2계정이 1row로 구성된 dts_FinBuf의 내용을 transaction을 수행하기 위해 1row로 구성된 dts_Fin로 변환한다.
    let i = 0,
        j = 0,
        s = "",
        arrIdx;
    for (i = 1; i <= dts_FinBuf.CountRow; i++) {
        for (j = 0; j < com.wconv.length(accIdxTop); j++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            arrIdx = (accIdxTop[j].colIdx > Math.ceil(dts_FinBuf.CountColumn / 2) ? scwin.getRgtIdxTop(i - 1) : i - 1); /*ORG SRC: dts_Fin.NameValue(1, accIdxTop[j].colHdr + "_" + accMapTop[arrIdx].colFtr) = dts_FinBuf.ColumnValue(i, accIdxTop[j].colIdx);*/ X = dts_FinBuf.ColumnValue(i, accIdxTop[j].colIdx);

            s = s + (s === "" ? "" : ((j % 3) === 0 ? "\n" : "--")) + accIdxTop[j].colHdr + "_" + accMapTop[arrIdx].colFtr + "," + dts_FinBuf.ColumnValue(i, accIdxTop[j].colIdx) + "," + dts_Fin.NameValue(1, accIdxTop[j].colHdr + "_" + accMapTop[arrIdx].colFtr);
        }
    }
    log.setValue(log.getValue() + "\n" + s);
};

