    const arrErr = new Array("INTERNAL", "UNDEFINDED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
    let errCnt = 0;
    let i = 0,
        j = 0;
    if (dts !== undefined) {
        for (i = 0; i < com.wconv.length(arrErr); i++) {

            errCnt = dts.SrvErrCount(arrErr[i]);
            for (j = 0; j < errCnt; j++) {

                alert("[CODE: " + dts.SrvErrCode(arrErr[i], j) + "] " + dts.SrvErrMsg(arrErr[i], j));
            }
        }
    }
};

