/**
 * @method
 * @name CInt
 * @description CInt 처리
 * @param {*} s s
 * @returns {void}
 * @hidden N
 */
scwin.CInt = function(s) {
    if (s === "") {
        return 0;
    } else if (isNaN(s)) {
        return 0;
    } else {
        return com.wconv.parseInt(s);
    }
};

