/**
 * @method
 * @name getCtrVal
 * @description get Ctr Val 처리
 * @param {*} s s
 * @returns {void}
 * @hidden N
 */
scwin.getCtrVal = function(s) {

    let o = document.getElementById(s);
    if (o !== undefined) {
        const oval = o.Text;
        if (oval === "") {
            return 0;
        } else if (isNaN(oval)) {
            return 0;
        } else {
            return com.wconv.parseInt(oval);
        }
    } else {
        alert("[" + s + "] is undefined");
        return 0;
    }
};

/**
 * @method
 * @name wrtCalCtr
 * @description wrt Cal Ctr 처리
 * @param {*} o o
 * @returns {void}
 * @hidden N
 */
scwin.wrtCalCtr = function(o) {
    let valTot = 0,
        arro, arr, valTmp;
    switch (tab.ActiveIndex) {
        case 1:
            {
                arr = scwin.getCalEntInfArr();
                break;
            }
        case 3:
            {
                arr = scwin.getCalStkArr();
                break;
            }
        case 4:
            {
                arr = scwin.getCalVCArr();
                break;
            }
        case 5:
            {
                arr = scwin.getCalInstArr();
                break;
            }
        case 9:
            {
                arr = scwin.getCalPrtArr();
                break;
            }
        default:
            {

            }
    }
    if (arr === undefined) {
        alert("arr is empty," + tab.ActiveIndex);
    }
    for (i = 0; i < com.wconv.length(arr); i++) {
        valCtr = 0;
        valTot = 0;
        if (arr[i][2] === "+") {
            for (j = 0; j < com.wconv.length(arr[i][0]); j++) {
                valTot += scwin.getCtrVal(arr[i][0][j]);
            }
        } else if (arr[i][2] === "/") {
            valTot = scwin.getCtrVal(arr[i][0][0]);
            for (j = 1; j < com.wconv.length(arr[i][0]); j++) {
                try {
                    valTmp = (arr[i][0][j] === "TotStk" ? scwin.getPrsntStkShrs() : scwin.getCtrVal(arr[i][0][j]));
                    valTot = (valTmp === 0 ? 0 : valTot / valTmp);
                } catch (err) {
                    alert("[" + arr[i][0][j] + "] 합산처리 중  오류");
                }
            }
            valTot = valTot * 100;
        } else if (arr[i][2] === "*") {
            valTot = 1;
            for (j = 0; j < com.wconv.length(arr[i][0]); j++) {
                valTot *= scwin.getCtrVal(arr[i][0][j]);
            }
        }

        arro = document.getElementById(arr[i][1]);
        if (arro !== undefined) {
            arro.Text = valTot.toFixed(2);
        } else {
            alert("[" + arr[i][0][j] + "] undefined");
        }
    }

    // 2008-09-19 종업원수 합계 수정
    let cnt_LgshrhdNmCount = 0;
    let cnt_Ovr5pctOwnrNmCount = 0;
    let cnt_Ovr1pctOwnrCount = 0;
    let personTot = 0;

    // 최대주주등
    if (txb_LgshrhdNm.getValue() !== "") {
        cnt_LgshrhdNmCount = 1;
    }
    // 5%이상 소유주주
    if (txb_Ovr5pctOwnrNm.getValue() !== "") {
        cnt_Ovr5pctOwnrNmCount = 1;
    }
    // 1%이상 소유주주
    if (txb_Ovr1pctOwnrNm.getValue() !== "") {
        cnt_Ovr1pctOwnrCount = 1;
    }
    personTot = cnt_LgshrhdNmCount + cnt_Ovr5pctOwnrNmCount + cnt_Ovr1pctOwnrCount;
    med_TotShrhdCnt.setValue(scwin.getCtrVal(arr[30][0][0]) + scwin.getCtrVal(arr[30][0][1]) + scwin.getCtrVal(arr[30][0][2]) + scwin.getCtrVal(arr[30][0][3]) + personTot);
};

/**
 * @method
 * @name getNewSeq
 * @description dataset에 자료추가시 새로운 sequence 키값을 얻기 위한 함수
 * @param {*} dtsNam dtsNam
 * @param {*} colNam colNam
 * @returns {void}
 * @hidden N
 */
scwin.getNewSeq = function(dtsNam, colNam) {
    let newSeq = 0;

    let o = document.getElementById(dtsNam);
    if (o !== undefined) {
        // log.Text = "MaxVal:" + (o.NameMax(colNam, 0, 0) + 1); NameMax는 string를 반환하지 않고 처리할수 없는 데이터를 반환
        for (let i = 1; i <= o.CountRow; i++) {

            newSeq = Math.max(newSeq, com.wconv.parseInt(o.NameString(i, colNam)));
        }
        return newSeq + 1;
    } else {
        return 1;
    }
};

