 * @name getPanDisabled
 * @description get Pan Disabled 처리
 * @param {*} p p
 * @returns {void}
 * @hidden N
 */
scwin.getPanDisabled = function(p) {
    for (let i = 0; i < com.wconv.length(scwin.arrPanDisabled); i++) {
        // array에 보관되어있던 해당panel의 disabled property 검색
        if (scwin.arrPanDisabled[i].panel === p) {
            return scwin.arrPanDisabled[i].disabled;
        }
    }
    return undefined;
};

/**
 * @method
 * @name setPanReadOnlyOnLoad
 * @description o: dataset, p: panel
 * @param {*} d d
 * @param {*} p p
 * @returns {void}
 * @hidden N
 */
scwin.setPanReadOnlyOnLoad = function(d, p) {
    // o: dataset, p: panel

    let oldVal = scwin.getPanDisabled(p);
    if (d === undefined) {
        if ((oldVal === undefined) || !oldVal) {
            //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
            scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
                panel: p,
                disabled: true
            };

            fn_setPanReadOnly(p);
        }
        scwin.panDisabled = true;
    } else {
        if (d.CountRow === 0) {

            fn_setPanReadOnly(p);
            /*
            if ((oldVal == undefined) || !oldVal) { //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
            	arrPanDisabled[arrPanDisabled.length] = {panel: p, disabled: true};

            	fn_setPanReadOnly(p);
            }
             */
            scwin.panDisabled = true;
            keyDisabled = ((d === dts_EntInf) || (d === dts_Fin) || (d === dts_Stk));
        } else {
            if ((oldVal === undefined) || oldVal) {
                //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
                scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
                    panel: p,
                    disabled: false
                };

                fn_setPanWritable2(p, scwin.getExcCtrs(p));
            }
            scwin.panDisabled = false;
            keyDisabled = !((d === dts_EntInf) || (d === dts_Fin) || (d === dts_Stk));
        }
    }
};

/**
 * @method
 * @name setPanWritableOnAdd
 * @description o: dataset, p: panel
 * @param {*} p p
 * @returns {void}
 * @hidden N
 */
scwin.setPanWritableOnAdd = function(p) {
    // o: dataset, p: panel
    let oldVal = scwin.getPanDisabled(p);
    if ((oldVal === undefined) || oldVal) {
        //  과거 해당panel의 disabled 상태가 없거나, 예전에는 false일 경우(수정가능상태)
        scwin.arrPanDisabled[scwin.arrPanDisabled.length] = {
            panel: p,
            disabled: false
        };

        fn_setPanWritable(p);
    }
    scwin.panDisabled = false;
};

