/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    let arr = com.wconv.split("?");

    return (com.wconv.length(arr) >= 1 ? frame.Provider("../" + arr[1]) : undefined);
};

