/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {

    frame.FrameShow("show");
    log.style.display = "none";
    let arr = new Array();

    /* 데이터셋 테스트용 코드임. 삭제할 것

    dts_EntInf.SetDataHeader("ADD_ASSGN_OPT_SHRS:BIGINT(15)");
    dts_EntInf.AddRow();

    dts_EntInf.NameValue(1, "ADD_ASSGN_OPT_SHRS:BIGINT") = "";
    return;
     */
    // temp dataset의 header를 지정한다.

    dts_FinBuf.SetDataHeader("ACC_NM_1:STRING(00),HALF_ACC_VAL_1:DECIMAL(26.8),FTRM_ACC_VAL_1:DECIMAL(26.8),STRM_ACC_VAL_1:DECIMAL(26.8),ACC_NM_2:STRING(00),HALF_ACC_VAL_2:DECIMAL(26.8),FTRM_ACC_VAL_2:DECIMAL(26.8),STRM_ACC_VAL_2:DECIMAL(26.8)");

    dts_FinBuf2.SetDataHeader("ACC_NM_1:STRING(00),HALF_ACC_VAL_1:DECIMAL(26.8),FTRM_ACC_VAL_1:DECIMAL(26.8),STRM_ACC_VAL_1:DECIMAL(26.8),ACC_NM_2:STRING(00),HALF_ACC_VAL_2:DECIMAL(26.8),FTRM_ACC_VAL_2:DECIMAL(26.8),STRM_ACC_VAL_2:DECIMAL(26.8)");
    await scwin.searchCode();

    const pvd = scwin.getProvider();
    if (pvd !== undefined) {

        scwin.fn_GetParOpn = pvd.scwin.fn_GetPar;

        scwin.fn_SetParOpn = pvd.scwin.fn_SetPar;
        frame.XPos = pvd.XPos + 100;
    }

    if (scwin.fn_GetParOpn !== undefined) {

        scwin.fn_GetParOpn(arr);
    }
    /*
    arr[0] = "03929";
    arr[1] = "920";
    arr[2] = "시험발행기관명";
     */
    txb_IsurCd.setValue((com.wconv.length(arr) >= 1 ? arr[0] : ""));
    txb_CoNm.setValue((com.wconv.length(arr) >= 3 ? arr[2] : "")); // 발행기관명도 넘겨받아 컨트롤에 반영해야 한다.

    if (com.wconv.length(arr) > 2) {
        await scwin.searchSubmitDate(arr[0], arr[1]);
    } else {

        scwin.setPanReadOnlyOnLoad(undefined, pan_Pub);

        scwin.setPanReadOnlyOnLoad(undefined, pan_ReqInf);
    }
};
